import{_ as r,C as s,o as a,c as l,a2 as n,b as d,w as o,a as i,E as g,a3 as p}from"./chunks/framework.DIWxYxwh.js";const B=JSON.parse('{"title":"上下文工程报告：用有限窗口撬动无限任务","description":"","frontmatter":{},"headers":[],"relativePath":"agent设计/OpenClaw上下文工程.md","filePath":"agent设计/OpenClaw上下文工程.md","lastUpdated":1791869861000}'),h={name:"agent设计/OpenClaw上下文工程.md"};function u(E,t,c,m,b,_){const e=s("Mermaid");return a(),l("div",null,[t[1]||(t[1]=n(`<h1 id="上下文工程报告-用有限窗口撬动无限任务" tabindex="-1">上下文工程报告：用有限窗口撬动无限任务 <a class="header-anchor" href="#上下文工程报告-用有限窗口撬动无限任务" aria-label="Permalink to &quot;上下文工程报告：用有限窗口撬动无限任务&quot;">​</a></h1><blockquote><p>结合《上下文工程》与《粘贴的文本》两份材料整理，面向开源技术文档场景。</p></blockquote><hr><h2 id="一、核心矛盾" tabindex="-1">一、核心矛盾 <a class="header-anchor" href="#一、核心矛盾" aria-label="Permalink to &quot;一、核心矛盾&quot;">​</a></h2><p><strong>无限任务复杂度 vs 有限上下文窗口。</strong></p><p>AI Agent 处理复杂任务（写长篇报告、全网检索验证、做视频）时，会产生海量中间信息：搜索网页、报错日志、历史记忆、多帧画面、资料条目。如果全部塞给大模型，会导致三个问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>表现</th></tr></thead><tbody><tr><td><strong>上下文爆炸（Context Overflow）</strong></td><td>Context Window 有限（如 128k token），塞不下，本轮直接失败或被迫从中间截断，截掉的可能是目标</td></tr><tr><td><strong>注意力稀释（Attention Dilution）</strong></td><td>大量无关原文、旧话题、整页网页夹在提示中间，模型丢掉当前要完成的那一句；中段内容尤其容易被忽略（Lost in the middle）</td></tr><tr><td><strong>成本与延迟上升</strong></td><td>每轮重发一大段历史；定时唤醒若也带上全部历史，花费按唤醒次数乘上去，推理速度极慢</td></tr></tbody></table><p><strong>解决思路：按需供给（On-Demand）与过滤（Filtering）。</strong></p><p>海量的中间过程留在模型外面，由运行时、专用节点或工具消化，窗口里只留下当前这一步要看的内容。</p><hr><h2 id="二、三大上下文工程策略" tabindex="-1">二、三大上下文工程策略 <a class="header-anchor" href="#二、三大上下文工程策略" aria-label="Permalink to &quot;二、三大上下文工程策略&quot;">​</a></h2><h3 id="策略一-宏观架构——subagent-与上下文折叠" tabindex="-1">策略一：宏观架构——Subagent 与上下文折叠 <a class="header-anchor" href="#策略一-宏观架构——subagent-与上下文折叠" aria-label="Permalink to &quot;策略一：宏观架构——Subagent 与上下文折叠&quot;">​</a></h3><p><strong>核心理解：主 Agent 不自己做所有搜索和阅读，采用分而治之的层级架构。</strong></p><ul><li><strong>主 Agent（Manager/Planner）</strong>：负责拆解任务，规划子任务，统筹全局。</li><li><strong>Subagent（Worker/Searcher）</strong>：负责执行具体搜索和阅读。例如派发一个 Subagent 去查某人的出版物，它去 Google Scholar 搜索、阅读十几篇论文摘要，最后只把总结后的一句结论返回给主 Agent。</li></ul><p><strong>上下文折叠（Context Folding）：</strong></p><ul><li>Subagent 探索过程中产生的几十万垃圾文本（整个网页 HTML、不相关论文全文），在任务结束时被“折叠”或“丢弃”。</li><li>只有提炼出的关键事实（Fact）被加入主 Agent 的上下文。</li><li>节点用过的原文随节点结束丢弃，不追加到主会话。</li></ul><p><strong>上下文长度曲线的锯齿状下降：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>长度</span></span>
<span class="line"><span> ↑</span></span>
<span class="line"><span> │    ╱╲          ╱╲          ╱╲</span></span>
<span class="line"><span> │   ╱  ╲        ╱  ╲        ╱  ╲</span></span>
<span class="line"><span> │  ╱    ╲______╱    ╲______╱    ╲______</span></span>
<span class="line"><span> │ ╱                                      ╲</span></span>
<span class="line"><span> └──────────────────────────────────────────→ 步骤</span></span>
<span class="line"><span>   Subagent执行   折叠    Subagent执行   折叠</span></span></code></pre></div><ul><li><strong>上升阶段</strong>：主 Agent 正在执行复杂搜索，或 Subagent 正在汇报探索结果，上下文增加。</li><li><strong>下降/停滞阶段</strong>：一个 Subagent 任务完成，其“工作记忆”（大量冗余文本）被清理（Context Pruning/Summarization），主 Agent 只保留最终结论，上下文长度大幅下降，腾出空间给下一个步骤。</li></ul><p><strong>并行节点：</strong></p><ul><li>几个节点并行时（例如一边组织要说的话、一边决定动作），它们不互相转发中间文本。</li><li>每条并行分支只看见开场装入的那份状态，以及自己这一支的材料。</li><li>分支之间只在结束时把各自的结论汇合，交给通道一起下发。</li></ul><p><strong>执行节点不再往下派生新的节点：</strong></p><ul><li>派生一层，就会再产生一份无人折叠的中间文本，锯齿下降就消失了。</li><li>需要多步时，由规划阶段一次写明串行顺序，后一步只接收前一步的结论。</li></ul><blockquote><p><strong>一句话总结</strong>：Subagent 在底层疯狂搜索，产生大量垃圾文本，但只把提炼后的最终结论返回给主 Agent。主 Agent 的上下文始终保持精简。</p></blockquote><hr><h3 id="策略二-记忆读取——按需检索与精准切片" tabindex="-1">策略二：记忆读取——按需检索与精准切片 <a class="header-anchor" href="#策略二-记忆读取——按需检索与精准切片" aria-label="Permalink to &quot;策略二：记忆读取——按需检索与精准切片&quot;">​</a></h3><p><strong>核心问题：为什么读 Memory 需要特别的工具？</strong></p><p>普通 ChatGPT 对话中，记忆通常直接拼接（Inject）到 Prompt 最前面。但在复杂 AI Agent 中，直接把记忆库（MEMORY.md 和 memory/*.md）全部塞进上下文会面临上述三个致命问题。</p><p><strong>解决方案：在 System Prompt 中制定规则——</strong></p><blockquote><p>在回答任何关于先前工作、决定、日期、人员、偏好或待办事项之前：先对 MEMORY.md + memory/*.md 执行 memory_search；然后使用 memory_get 仅提取所需行。</p></blockquote><p><strong>过滤流程：</strong></p><ol><li><strong>memory_search（搜索定位）</strong>：不读取全文，像搜索引擎一样，根据当前问题在记忆文件中找到相关片段/位置，大大缩小范围。</li><li><strong>memory_get（精准读取）</strong>：读取特定的记忆 Markdown 文件，可以指定起始行（starting line）和读取行数（N lines）。相当于 <code>tail</code> 或 <code>sed</code> 命令，只把真正需要的几行内容拉入当前上下文窗口。</li></ol><p><strong>对比：</strong></p><table tabindex="0"><thead><tr><th>传统方式</th><th>OpenClaw 方式</th></tr></thead><tbody><tr><td>模型 → 直接加载整个文件 → 上下文爆满</td><td>模型 → 思考（我需要查记忆）→ 调用 memory_search（外部系统检索）→ 得到线索 → 调用 memory_get（外部系统精准切片）→ 只将提取出的几行（极少 Token）喂给模型生成最终回答</td></tr></tbody></table><p><strong>与开场装配的对应关系：</strong></p><p>每一轮开场，运行时拼一份提示，其中与「此前发生过什么」有关的部分只有三块：</p><table tabindex="0"><thead><tr><th>块</th><th>内容</th><th>说明</th></tr></thead><tbody><tr><td><strong>最近若干轮原文</strong></td><td>就近的对话保持原话</td><td>保证代词、追问和刚确认的事项还在</td></tr><tr><td><strong>少量长期事实</strong></td><td>按当前这句话检索，只取回几条相关记录</td><td>检索不到就这一块为空；用户的全部历史不进入提示</td></tr><tr><td><strong>一份较早摘要</strong></td><td>有字数上限的客观叙述</td><td>由更早内容压缩而来；保留事实、偏好、约定和未完成事项，去掉寒暄和重复</td></tr></tbody></table><blockquote><p>摘要必须标成背景：放进一个单独的回合，开头写明「这是更早对话的压缩，不是本轮用户原话」，模型才不会把它当成用户刚刚说的话或一条新的系统指令。身份说明仍然是提示开头唯一的系统段——再追加一条系统消息，会和不少接口「系统段只出现在开头」的要求冲突。</p></blockquote><blockquote><p><strong>一句话总结</strong>：不要指望大模型自己“假装”记住了所有东西。通过在 System Prompt 中硬性规定调用 memory_search 和 memory_get，将复杂的内存管理逻辑剥离给外部代码（Python/Node.js 脚本），让大模型只负责“决策需要什么数据”，让外部工具负责“高效过滤和提取数据”。</p></blockquote><hr><h3 id="策略三-工具调用——动态按需加载-lazy-loading" tabindex="-1">策略三：工具调用——动态按需加载（Lazy Loading） <a class="header-anchor" href="#策略三-工具调用——动态按需加载-lazy-loading" aria-label="Permalink to &quot;策略三：工具调用——动态按需加载（Lazy Loading）&quot;">​</a></h3><p><strong>场景</strong>：用户下达“做一支自我介绍的视频”时，Agent 不会盲目执行，而是先去指定目录寻找是否有相关的 SKILL.md 文件。</p><p><strong>上下文工程的核心体现（System Prompt 动态组装）：</strong></p><ul><li><strong>按需读取（Lazy Loading）</strong>：System Prompt 中并没有直接塞入所有技能的具体代码，而是只给了一个目录/清单（列出技能名和路径，并提示“有需要请读取”）。</li><li><strong>避免上下文污染</strong>：如果一次性把所有 Skill 的详细步骤都塞进 System Prompt，会消耗大量 Token 并可能干扰模型判断。通过“按需读取”，只为当前任务提供最精准的上下文。</li></ul><p><strong>工具调用（Tool Use）：</strong></p><ul><li>当模型意识到需要“做视频”这个技能时，它会根据 System Prompt 中的路径指引，自主发出 <code>[tool_use] Read(video/SKILL.md)</code> 的指令去读取具体操作指南，随后直接执行该工具。</li></ul><p><strong>与技能/资料按需进入的对应关系：</strong></p><ul><li>技能的步骤、领域手册都不放进开场提示。</li><li>开场只放技能名称和一句话适用时机；模型判定这一轮用得上，再读取那一份说明，读入的是这一份，不是目录里的全部。</li><li>领域资料由执行节点按当前问题检索。命中的条目进入该节点的提示，手册的其余部分留在库里。检索为空，节点就在没有资料的情况下回答，或者明确说没有查到，而不是退回去把整本手册装进窗口。</li></ul><blockquote><p><strong>一句话总结</strong>：AI Agent 不是一次性接收所有工具说明，而是通过 System Prompt 提供技能索引，让模型在需要时（按需）主动去读取具体的 SKILL.md，这是上下文工程中优化 Token 和提升模型执行准确率的关键技巧。</p></blockquote><hr><h2 id="三、辅助机制" tabindex="-1">三、辅助机制 <a class="header-anchor" href="#三、辅助机制" aria-label="Permalink to &quot;三、辅助机制&quot;">​</a></h2><h3 id="_3-1-周期滑动窗口摘要" tabindex="-1">3.1 周期滑动窗口摘要 <a class="header-anchor" href="#_3-1-周期滑动窗口摘要" aria-label="Permalink to &quot;3.1 周期滑动窗口摘要&quot;">​</a></h3><p>工作记忆有轮次上限。挤出的一轮不能直接丢掉，否则追问会断；也不能把挤出的原文继续堆在提示里，否则窗口只是换了个地方变长。</p>`,53)),(a(),d(p,null,{default:o(()=>[g(e,{id:"mermaid-351",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E5%B7%B2%E6%9C%89%E6%91%98%E8%A6%81%22%5D%20--%3E%20C%5B%22%E5%8E%8B%E7%BC%A9%E8%B0%83%E7%94%A8%3Cbr%2F%3E%E5%9B%BA%E5%AE%9A%E8%AF%B4%E6%98%8E%EF%BC%9A%E7%BB%BC%E5%90%88%E8%A6%81%E7%82%B9%20%C2%B7%20%E4%BF%9D%E7%95%99%E4%BA%8B%E5%AE%9E%2F%E5%81%8F%E5%A5%BD%2F%E7%BA%A6%E5%AE%9A%2F%E6%9C%AA%E5%AE%8C%E6%88%90%E4%BA%8B%E9%A1%B9%20%C2%B7%20%E5%8E%BB%E6%8E%89%E5%AF%92%E6%9A%84%20%C2%B7%20%E4%B8%8D%E7%BC%96%E9%80%A0%20%C2%B7%20%E4%B8%8D%E8%B6%85%E8%BF%87%E5%AD%97%E6%95%B0%E4%B8%8A%E9%99%90%22%5D%0A%20%20%20%20B%5B%22%E6%96%B0%E6%8C%A4%E5%87%BA%E7%9A%84%E4%B8%80%E8%BD%AE%E6%88%96%E5%87%A0%E8%BD%AE%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%5B%22%E6%96%B0%E6%91%98%E8%A6%81%3Cbr%2F%3E%E5%8F%97%E5%90%8C%E4%B8%80%E5%AD%97%E6%95%B0%E4%B8%8A%E9%99%90%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n('<ul><li>设定固定的 token 阈值（如 100k），触发总结最近的对话历史。</li><li>将摘要替换掉原始文本。</li><li>合并可以攒几轮再做一次，避免每一轮都为了压缩再调用一次模型。</li><li>新摘要仍然受同一个字数上限约束，所以提示里的摘要段不会随对话无限变长。</li></ul><h3 id="_3-2-压缩指南的自动迭代" tabindex="-1">3.2 压缩指南的自动迭代 <a class="header-anchor" href="#_3-2-压缩指南的自动迭代" aria-label="Permalink to &quot;3.2 压缩指南的自动迭代&quot;">​</a></h3><p>以“完整上下文成功、压缩上下文失败”的对比轨迹作为反馈：</p><ul><li>当完整上下文能做对、压缩之后做错时，把这两次轨迹放在一起；</li><li>让 LLM 分析“压缩时漏掉了哪条事实或约定”；</li><li>然后改写压缩说明；</li><li>说明变好之后，下一次合并沿用新说明。</li></ul><hr><h2 id="四、核心原则总结" tabindex="-1">四、核心原则总结 <a class="header-anchor" href="#四、核心原则总结" aria-label="Permalink to &quot;四、核心原则总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td><strong>按需供给</strong></td><td>窗口里只放当前这一步要看的内容</td></tr><tr><td><strong>三块记忆</strong></td><td>最近原文 + 少量检索事实 + 一份受限摘要</td></tr><tr><td><strong>摘要滚动</strong></td><td>挤出轮次压缩合并，受同一字数上限约束；压缩说明可迭代改进</td></tr><tr><td><strong>专用节点</strong></td><td>中间文本在节点内消化，只交回结论，主会话呈锯齿状</td></tr><tr><td><strong>并行不转发</strong></td><td>分支各自看开场状态，结束时汇合结论</td></tr><tr><td><strong>执行节点不派生</strong></td><td>多步由规划阶段串行写明</td></tr><tr><td><strong>技能资料按需读</strong></td><td>开场只放名称和适用时机，用时再读单份</td></tr></tbody></table><hr><h2 id="五、收尾-一句话总结" tabindex="-1">五、收尾：一句话总结 <a class="header-anchor" href="#五、收尾-一句话总结" aria-label="Permalink to &quot;五、收尾：一句话总结&quot;">​</a></h2><p>一个核心矛盾：<strong>无限的任务复杂度 vs 有限的上下文窗口。</strong></p><p>三大解决策略：</p><ol><li><strong>宏观架构</strong>：Subagent 与上下文折叠。</li><li><strong>记忆读取</strong>：按需检索与精准切片（memory_search + memory_get）。</li><li><strong>工具调用</strong>：动态按需加载（Lazy Loading）。</li></ol><p><strong>总结成一句话：</strong></p><blockquote><p>高级 AI Agent 的上下文工程，本质上是建立了一套“外部动态供给系统”——让大模型始终只看到与当前决策最相关、最精简的信息，把海量的中间过程和冗余知识留在模型外部（由 Subagent 或外部工具处理），从而用有限的上下文窗口撬动无限复杂的任务。</p></blockquote>',14))])}const k=r(h,[["render",u]]);export{B as __pageData,k as default};
